/** Compile-only registered-player integration fixtures for owned revolver shots. */
@GameTestTags({"gun-fire", "owned-combat"})
@PrefixGameTestTemplate(false)
public final class RegisteredGunFireGameTests {
    private RegisteredGunFireGameTests() { }

    @GameTest(template="atmos_large_empty",templateNamespace="moonstation14",batch="registered_gun_fire_python",timeoutTicks=100)
    public static void registeredPythonShotCommitsAmmoRejectsReplayAndPublishesProjectile(GameTestHelper h) {
        var gunItem=com.juicyslew.moonstation14.item.ModItems.WEAPON_REVOLVER_PYTHON.get();
        var cartridgeItem=com.juicyslew.moonstation14.item.ModItems.CARTRIDGE_MAGNUM.get();
        var gunId=net.minecraft.core.registries.BuiltInRegistries.ITEM.getKey(gunItem);
        var cartridgeId=net.minecraft.core.registries.BuiltInRegistries.ITEM.getKey(cartridgeItem);
        var projectileId=ResourceLocation.fromNamespaceAndPath("moonstation14","fixture_python_projectile");
        var tag=ResourceLocation.fromNamespaceAndPath("moonstation14","fixture_magnum");
        ScopedPrototypeCatalogFixture.replace(h,ModGunProfiles.TYPE,c->{c.put(gunId,new GunProfile(new GunProfile.GunData(2f,40f,false,"SEMI_AUTO",Optional.empty(),Optional.empty()),Optional.of(new GunProfile.RevolverAmmoProviderData(6,cartridgeId,Set.of(tag),Set.of()))));return c;});
        ScopedPrototypeCatalogFixture.replace(h,ModCartridgeProfiles.TYPE,c->{c.put(cartridgeId,new CartridgeProfile(projectileId,false,Set.of(tag)));return c;});
        ScopedPrototypeCatalogFixture.replace(h,ModProjectileProfiles.TYPE,c->{c.put(projectileId,new ProjectileProfile(Map.of("piercing",35f),true,true,10f));return c;});
        var fixture=RegisteredServerPlayerFixture.register(h.getLevel(),"registered-python-shot");
        var owned=new ArrayList<net.minecraft.world.entity.Entity>();var done=new java.util.concurrent.atomic.AtomicBoolean();Runnable cleanup=()->{if(!done.compareAndSet(false,true))return;for(var e:owned)if(!e.isRemoved())e.discard();fixture.close();};
        h.testInfo.addListener(new net.minecraft.gametest.framework.GameTestListener(){private void clean(){cleanup.run();}@Override public void testStructureLoaded(net.minecraft.gametest.framework.GameTestInfo i){}@Override public void testPassed(net.minecraft.gametest.framework.GameTestInfo i,net.minecraft.gametest.framework.GameTestRunner r){clean();}@Override public void testFailed(net.minecraft.gametest.framework.GameTestInfo i,net.minecraft.gametest.framework.GameTestRunner r){clean();}@Override public void testAddedForRerun(net.minecraft.gametest.framework.GameTestInfo o,net.minecraft.gametest.framework.GameTestInfo n,net.minecraft.gametest.framework.GameTestRunner r){clean();}});
        try{h.runAtTickTime(2,()->{try{var active=RegisteredPlayerReadyDriver.readyAndQuery(fixture);var body=active.body();owned.add(body);var pos=h.absolutePos(new net.minecraft.core.BlockPos(3,2,3));body.teleportTo(pos.getX()+.5,pos.getY(),pos.getZ()+.5);body.setYRot(0);body.setDeltaMovement(Vec3.ZERO);body.tick();var hands=body.getExistingDataOrNull(com.juicyslew.moonstation14.component.ModDataAttachments.LIVE_HANDS.get());var hand=hands.activeHand();var sourceStack=new net.minecraft.world.item.ItemStack(gunItem);sourceStack.set(net.minecraft.core.component.DataComponents.CUSTOM_NAME,net.minecraft.network.chat.Component.literal("fixture python").withStyle(s->s.withColor(0xabcdef)));var source=com.juicyslew.moonstation14.entities.LooseItemEntity.create(h.getLevel(),body.getEyePosition().add(body.getLookAngle().scale(.7)),sourceStack);source.setNoGravity(true);owned.add(source);if(!h.getLevel().addFreshEntity(source)||com.juicyslew.moonstation14.ms14.hands.live.BodyHandItemTransfer.pickupSelected(fixture.player(),source.getUUID(),hand,hands.revision(),ignored->{})!=com.juicyslew.moonstation14.ms14.hands.live.BodyHandItemTransfer.Result.SUCCESS)throw new GameTestAssertException("actual authenticated Python pickup failed");var current=body.getExistingDataOrNull(com.juicyslew.moonstation14.component.ModDataAttachments.LIVE_HANDS.get());var token=current.token(hand).orElseThrow();var target=EntityType.VILLAGER.create(h.getLevel());if(target==null)throw new GameTestAssertException("target creation");owned.add(target);target.setNoAi(true);target.setPos(body.getX(),body.getY(),body.getZ()+3);h.getLevel().addFreshEntity(target);var before=new HashSet<UUID>();for(var e:h.getLevel().getEntities().getAll())before.add(e.getUUID());var select=GunWeaponResolver.resolve(body).orElseThrow(()->new GameTestAssertException("registered selected gun did not resolve"));var oldRevision=select.handRevision();CombatModeRequestService.handle(fixture.player(),new CombatModeRequest(active.epoch(),1,true));var aim=target.position().add(0,target.getBbHeight()*.55,0);var request=new GunShotRequest(active.epoch(),1,oldRevision,hand,token,aim);var reply=GunShotRequestService.handle(fixture.player(),request);if(reply.status()!=GunFireSystem.Status.FIRED||!reply.consumedSource()||reply.handRevision()<=oldRevision||!token.equals(reply.itemToken())||reply.remainingTicks()!=10)throw new GameTestAssertException("actual registered shot request did not fire/acknowledge fresh binding");var afterHands=body.getExistingDataOrNull(com.juicyslew.moonstation14.component.ModDataAttachments.LIVE_HANDS.get());var gun=afterHands.stackCopy(hand).orElseThrow();var revolver=gun.get(com.juicyslew.moonstation14.component.ModDataComponents.REVOLVER_STATE.get());if(revolver==null||revolver.index()!=1||revolver.chambers().size()!=6||!revolver.chambers().get(0).physical().orElseThrow().getItem().equals(cartridgeItem)||!Boolean.TRUE.equals(revolver.chambers().get(0).physical().orElseThrow().get(com.juicyslew.moonstation14.component.ModDataComponents.CARTRIDGE_SPENT.get()))||!Objects.equals(gun.get(net.minecraft.core.component.DataComponents.CUSTOM_NAME),sourceStack.get(net.minecraft.core.component.DataComponents.CUSTOM_NAME))||gun.getCount()!=1||!token.equals(afterHands.token(hand).orElse(null)))throw new GameTestAssertException("committed Python source/ammo state is not preserved");var projectiles=new ArrayList<com.juicyslew.moonstation14.entities.TypedProjectileEntity>();for(var e:h.getLevel().getEntities().getAll())if(e instanceof com.juicyslew.moonstation14.entities.TypedProjectileEntity p&&!before.contains(p.getUUID())){projectiles.add(p);owned.add(p);}if(projectiles.size()!=1)throw new GameTestAssertException("expected one newly published typed projectile");var stale=GunShotRequestService.handle(fixture.player(),request);if(stale.status()!=GunFireSystem.Status.REJECTED||stale.consumedSource())throw new GameTestAssertException("exact replay was not rejected");var staleBinding=GunShotRequestService.handle(fixture.player(),new GunShotRequest(active.epoch(),2,oldRevision,hand,token,aim));if(staleBinding.status()!=GunFireSystem.Status.REJECTED||staleBinding.consumedSource())throw new GameTestAssertException("new-sequence stale hand revision was not rejected");var currentGun=GunWeaponResolver.readOwned(body,GunWeaponResolver.resolve(body).orElseThrow()).orElseThrow().stack();if(!Objects.equals(currentGun.get(com.juicyslew.moonstation14.component.ModDataComponents.REVOLVER_STATE.get()),revolver))throw new GameTestAssertException("stale binding changed committed ammunition");var afterProjectileIds=new HashSet<UUID>();for(var e:h.getLevel().getEntities().getAll())if(e instanceof com.juicyslew.moonstation14.entities.TypedProjectileEntity)afterProjectileIds.add(e.getUUID());if(afterProjectileIds.size()!=1)throw new GameTestAssertException("replay/stale binding published another projectile");h.runAfterDelay(6,()->{try{if(target.isRemoved()||target.getHealth()>=target.getMaxHealth()||target.getExistingDataOrNull(com.juicyslew.moonstation14.component.ModDataAttachments.DAMAGE.get())==null||target.getExistingDataOrNull(com.juicyslew.moonstation14.component.ModDataAttachments.DAMAGE.get()).getMap().getOrDefault("piercing",0f)<35f)throw new GameTestAssertException("normal world ticks did not resolve projectile impact damage");if(!projectiles.get(0).isRemoved())throw new GameTestAssertException("impact projectile did not delete on collision");h.succeed();}catch(RuntimeException|Error e){cleanup.run();throw e;}});}catch(RuntimeException|Error e){cleanup.run();throw e;}});}catch(RuntimeException|Error e){cleanup.run();throw e;}
    }
}
